function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 500) return 'nums needs 1 to 500 values.';
  if (!nums.every(v => Number.isInteger(v) && v >= 1 && v <= 100000)) return 'Each value is between 1 and 10^5.';
  return null;
}

