function findNumbers(nums) {
  let count = 0;

  for (const num of nums) {
    let digits = 1;
    let rest = num;
    while (rest >= 10) {
      rest = Math.floor(rest / 10);
      digits++;
    }
    if (digits % 2 === 0) {
      count++;
    }
  }
  return count;
}

