function generate(rand, size) {
  const n = size === 'large' ? 500 : 1 + Math.floor(rand() * 10);
  const nums = [];
  for (let i = 0; i < n; i++) {
    // Pick the digit count first so short and long numbers both show up often.
    const digits = 1 + Math.floor(rand() * 6);
    const low = 10 ** (digits - 1);
    const high = Math.min(10 ** digits - 1, 100000);
    const edge = rand();
    nums.push(edge < 0.15 ? low : edge < 0.3 ? high : low + Math.floor(rand() * (high - low + 1)));
  }
  return [nums];
}
